\set ON_ERROR_STOP on

do $$
declare
    v_count integer;
begin
    select count(*)
    into v_count
    from registry.items
    where id in (
        '00000000-0000-4000-8000-000000000055',
        '00000000-0000-4000-8000-000000000056',
        '00000000-0000-4000-8000-000000000057',
        '00000000-0000-4000-8000-000000000058',
        '00000000-0000-4000-8000-000000000059',
        '00000000-0000-4000-8000-000000000060',
        '00000000-0000-4000-8000-000000000062',
        '00000000-0000-4000-8000-000000000063',
        '00000000-0000-4000-8000-000000000064',
        '00000000-0000-4000-8000-000000000065',
        '00000000-0000-4000-8000-000000000066',
        '00000000-0000-4000-8000-000000000067',
        '00000000-0000-4000-8000-000000000068',
        '00000000-0000-4000-8000-000000000069',
        '00000000-0000-4000-8000-000000000070',
        '00000000-0000-4000-8000-000000000071',
        '00000000-0000-4000-8000-000000000072',
        '00000000-0000-4000-8000-000000000073',
        '00000000-0000-4000-8000-000000000074',
        '00000000-0000-4000-8000-000000000076',
        '00000000-0000-4000-8000-000000000077',
        '00000000-0000-4000-8000-000000000078',
        '00000000-0000-4000-8000-000000000079',
        '00000000-0000-4000-8000-000000000080',
        '00000000-0000-4000-8000-000000000081',
        '00000000-0000-4000-8000-000000000082',
        '00000000-0000-4000-8000-000000000083',
        '00000000-0000-4000-8000-000000000084',
        '00000000-0000-4000-8000-000000000085',
        '00000000-0000-4000-8000-000000000086',
        '00000000-0000-4000-8000-000000000087',
        '00000000-0000-4000-8000-000000000088',
        '00000000-0000-4000-8000-000000000091'
    )
      and is_enabled;

    if v_count <> 33 then
        raise exception 'Expected 33 enabled merged-list items, found %', v_count;
    end if;

    select count(*)
    into v_count
    from registry.items
    where id in (
        '00000000-0000-4000-8000-000000000086',
        '00000000-0000-4000-8000-000000000087',
        '00000000-0000-4000-8000-000000000088'
    )
      and category = 'Care and bath'
      and claim_mode = 'multiple'
      and max_claims = 3
      and is_enabled;

    if v_count <> 3 then
        raise exception 'Nappy size configuration is incomplete';
    end if;

    select count(*)
    into v_count
    from registry.items
    where id in (
        '33333333-3333-4333-8333-333333333333',
        '00000000-0000-4000-8000-000000000053',
        '00000000-0000-4000-8000-000000000022',
        '00000000-0000-4000-8000-000000000023',
        '00000000-0000-4000-8000-000000000013',
        '11111111-1111-4111-8111-111111111111'
    )
      and is_enabled;

    if v_count <> 0 then
        raise exception 'An explicitly excluded registry item was re-enabled';
    end if;
end;
$$;

\echo PASS: merged Afrikaans wish lists are configured safely
